PROGRAM ST480_LIMDISPENSERING
VAR
    steg        : INT := 0;
    tmrFlode    : TON;
    tmrStrang   : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xKassera    : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran en certifierad sakerhets-PLC och lases bara. Den har
   logiken ror inte sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

(* Flodet far byggas upp innan det doms. Munstycket ar 3,0 mm och pumpen
   behover en dryg tiondel pa att fylla det; 0,5 s ar flera ganger den tiden
   och hindrar att varje strang larmar pa sina forsta tiondelar. *)
tmrFlode(IN := ST480_ADH_ON, PT := T#500ms);

(* Strangen foljer flansens omkrets 760 mm vid 120 mm/s och tar 6,33 s.
   Vakten pa 8,0 s faller nar roboten inte blir klar med sin bana. *)
tmrStrang(IN := ST480_RB_START, PT := T#8s);

(* --- larmkallorna samlas fore domen --- *)

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* En strang som avbryts mitt i ar en kasserad detalj oavsett vad som avbrot
   den. Detaljen far aldrig ga vidare omarkt. *)
IF ST480_ADH_ON AND (NOT EMG_OK OR NOT AIR_OK OR NOT SYS_AUTO) THEN
    xKassera := TRUE;
END_IF;

(* Flodesfonstret 45,0 till 57,0 cm3/min kring det raknade 50,9 cm3/min. Under
   fonstret ar munstycket igensatt eller materialet slut, over det ar
   munstycket slitet eller matningstrycket for hogt. Bada ger en strang som
   inte tatar, sa strangen stoppas OCH detaljen markas. *)
IF tmrFlode.Q AND (ST480_ADH_FLW < 45.0 OR ST480_ADH_FLW > 57.0) THEN
    xLarm := TRUE;
    xKassera := TRUE;
END_IF;

IF tmrStrang.Q THEN
    xLarm := TRUE;
    xKassera := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET. Ett aterstallt
   nodstopp startar ingenting. *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT EMG_OK THEN
    ST480_CNV_RUN := FALSE;
    ST480_CLP_CLOSE := FALSE;
    ST480_RB_START := FALSE;
    ST480_ADH_ON := FALSE;
    steg := 0;
ELSIF NOT xDriftsklar THEN
    (* Larm eller vantad kvittens. Roboten stoppas och doseringsventilen
       stangs i samma scan. Klamman lamnas dar den star: en detalj med
       avbruten strang far inte lossna ur fixturen for att larmet kom. *)
    ST480_CNV_RUN := FALSE;
    ST480_RB_START := FALSE;
    ST480_ADH_ON := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST480_CNV_RUN := TRUE;
            ST480_CLP_CLOSE := FALSE;
            IF NOT ST480_PRT_PRS THEN
                (* Den markta detaljen har lamnat stationen. *)
                xKassera := FALSE;
            ELSIF NOT xKassera AND NOT ST480_ADH_LOW THEN
                ST480_CNV_RUN := FALSE;
                ST480_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Doseringen far borja forst nar fixturen bekraftat att detaljen
               sitter fast. En strang pa en los detalj hamnar bredvid fogen. *)
            IF ST480_CLP_CLOSED THEN
                ST480_RB_START := TRUE;
                steg := 2;
            END_IF;
        2:
            ST480_ADH_ON := TRUE;
            IF ST480_RB_DONE THEN
                (* Ventilen stangs i SAMMA scan som roboten blir klar. Star
                   den kvar oppen med roboten stilla rinner limmet ut i en
                   klump som nasta detalj pressar ut i fogen. *)
                ST480_ADH_ON := FALSE;
                ST480_RB_START := FALSE;
                steg := 3;
            END_IF;
        3:
            ST480_CLP_CLOSE := FALSE;
            steg := 4;
        4:
            IF NOT ST480_CLP_CLOSED THEN
                ST480_CNV_RUN := TRUE;
                steg := 5;
            END_IF;
        5:
            IF NOT ST480_PRT_PRS THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Markeringen foljer kassationsbeslutet sa lange nodstoppet ar slutet. En
   detalj med avbruten strang far aldrig ga vidare omarkt, sa markeringen far
   inte falla for att larmet kom eller for att nagon kvitterat. *)
ST480_REJ_MARK := xKassera AND EMG_OK;
END_PROGRAM

